<?php
require_once __DIR__.'/../includes/auth.php';
if(!isAdmin()){http_response_code(403);exit('Khusus Admin.');}
require_once __DIR__.'/../includes/pembaruan_helper.php';
$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
if($_SERVER['REQUEST_METHOD']==='POST')try{
    layananValidasiToken();$id=(int)($_POST['id']??0);$setuju=isset($_POST['setujui']);$catatan=trim((string)($_POST['catatan']??''));$db->beginTransaction();
    $tgl=putuskanMutasiHariAngsuran($db,$id,(int)$_SESSION['user_id'],$setuju,$catatan);
    $q=$db->prepare('SELECT jenis,pinjaman_id FROM pengajuan_mutasi_angsuran WHERE id=?');$q->execute([$id]);$mutasi=$q->fetch(PDO::FETCH_ASSOC);
    if($setuju&&$mutasi&&$mutasi['jenis']==='hari'){
        perbaruiJadwalHariLibur($db,(int)$mutasi['pinjaman_id']);
        $q=$db->prepare("SELECT MIN(tanggal_jatuh_tempo) FROM angsuran WHERE pinjaman_id=? AND status<>'lunas'");$q->execute([(int)$mutasi['pinjaman_id']]);$tgl=$q->fetchColumn()?:$tgl;
        $db->prepare('UPDATE pengajuan_mutasi_angsuran SET tanggal_efektif=? WHERE id=?')->execute([$tgl,$id]);
    }
    $db->commit();$_SESSION['success']=$setuju?'Permohonan disetujui. Tanggal efektif: '.$tgl:'Permohonan ditolak.';
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$_SESSION['error']=$e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST'){header('Location: mutasi_angsuran.php');exit;}
$rows=$db->query("SELECT m.*,p.kode_pinjaman,p.frekuensi,a.nama_lengkap,kl.nama kelompok_lama,kb.nama kelompok_baru FROM pengajuan_mutasi_angsuran m JOIN pinjaman p ON p.id=m.pinjaman_id JOIN anggota a ON a.id=m.anggota_id LEFT JOIN kelompok_angsuran kl ON kl.id=m.kelompok_lama_id LEFT JOIN kelompok_angsuran kb ON kb.id=m.kelompok_baru_id WHERE m.jenis IN ('hari','kelompok') ORDER BY (m.status='menunggu') DESC,m.diajukan_pada DESC LIMIT 300")->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mutasi Kelompok dan Hari</title><?php $uiAssetPrefix='../';include __DIR__.'/../includes/layout/assets.php';?></head><body><?php include __DIR__.'/../includes/layout/shell_start.php';?><div class="ui-tx-page"><header class="ui-dash-header"><div class="ui-dash-header-icon"><i class="ti ti-calendar-cog"></i></div><div class="ui-dash-header-copy"><p class="ui-dash-eyebrow mb-0">Peminjaman · Admin</p><h1 class="ui-dash-title">Mutasi Kelompok / Hari Angsuran</h1><p class="ui-dash-meta mb-0">Perpindahan hanya diproses setelah seluruh angsuran yang telah jatuh tempo lunas. Pindah hari mengubah jadwal; pindah kelompok hanya mengubah kelompok penagihan.</p></div></header><?php ui_flash();?><div class="card"><div class="table-responsive"><table class="table table-striped align-middle mb-0"><thead><tr><th>Anggota</th><th>Pinjaman</th><th>Jenis</th><th>Perubahan</th><th>Alasan</th><th>Diajukan</th><th>Status / keputusan</th></tr></thead><tbody><?php foreach($rows as $r):$perubahan=$r['jenis']==='hari'?labelHariAngsuran($r['hari_lama']).' → '.labelHariAngsuran($r['hari_baru']):($r['kelompok_lama']?:'Belum ada kelompok').' → '.($r['kelompok_baru']?:'Kelompok tidak tersedia');?><tr><td><?=htmlspecialchars($r['nama_lengkap'])?></td><td><?=htmlspecialchars($r['kode_pinjaman'].' · '.$r['frekuensi'])?></td><td><?=htmlspecialchars($r['jenis']==='hari'?'Hari':'Kelompok')?></td><td><?=htmlspecialchars($perubahan)?></td><td><?=nl2br(htmlspecialchars($r['alasan']))?></td><td><?=htmlspecialchars($r['diajukan_pada'])?></td><td><?php if($r['status']==='menunggu'):?><form method="post" class="d-flex flex-column gap-2"><?=layananToken()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input name="catatan" class="form-control form-control-sm" maxlength="2000" placeholder="Catatan (opsional)"><div class="d-flex gap-2"><button class="btn btn-sm btn-success" name="setujui" value="1" onclick="return confirm('Setujui permohonan mutasi ini?')">Setujui</button><button class="btn btn-sm btn-outline-danger" name="tolak" value="1">Tolak</button></div></form><?php else:?><?=htmlspecialchars($r['status'].' · efektif '.($r['tanggal_efektif']??'—'))?><div class="small text-muted"><?=htmlspecialchars($r['catatan_admin']??'')?></div><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php if(!$rows):?><div class="card-body text-muted">Belum ada permohonan.</div><?php endif?></div></div><?php include __DIR__.'/../includes/layout/shell_end.php';?></body></html>
